pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address addr, uint256 amount) public {
        // Bound amount to avoid overflow beyond the contract balance that might be used elsewhere
        amount = bound(amount, 0, 1000000 ether);
        // Ensure addr is not the zero address to avoid issues in transfer
        vm.assume(addr != address(0));

        // Get balance before deposit
        uint256 balanceBefore = c.balances(addr);

        // Deal ether to addr for deposit
        vm.deal(addr, amount);
        // Call deposit from addr
        vm.prank(addr);
        c.deposit{value: amount}();

        // Get balance after deposit
        uint256 balanceAfter = c.balances(addr);

        // General rule: balanceAfter = balanceBefore + amount
        assertTrue(balanceAfter == balanceBefore + amount, "Deposit does not increase balance correctly");
    }
}

