pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // Bound deposit and withdraw to realistic values
        depositAmount = bound(depositAmount, 1, 1e18);
        withdrawAmount = bound(withdrawAmount, 1, depositAmount);

        // Deal ether to test contract, then send to C as deposit
        address testContract = address(this);
        vm.deal(testContract, depositAmount);

        // Deposit
        (bool successDeposit, ) = address(c).call{value: depositAmount}(abi.encodeWithSignature("deposit()"));
        if (!successDeposit) return; // skip if deposit reverts

        // Perform a partial withdraw
        (bool successWithdraw, ) = address(c).call(abi.encodeWithSignature("withdraw(uint256)", withdrawAmount));
        if (!successWithdraw) return; // skip if withdraw reverts (should not if amount <= balance)

        // After withdraw, user's balance should be depositAmount - withdrawAmount
        uint256 userBalance = c.balances(address(this));
        assertTrue(userBalance == depositAmount - withdrawAmount, "Balance not updated correctly after withdraw");
    }
}

